/**
 * MVP132 — private cron scheduled document recovery.
 * Token generated inside Vault, verified by service_role SQL RPC.
 * Does not send WhatsApp, expose source bytes or return private identifiers.
 */
import {createClient} from 'npm:@supabase/supabase-js@2.118.0';
import {recoverOneStoredDocument} from '../cotironda-piloto-whapi/private-document-recovery.ts';
import {runRecoveryService} from './logic.ts';
import {diagnoseOneStoredQuote} from './quote-reconciliation.ts';
import {correctArchivedSupplierRole} from './supplier-role-recovery.ts';
import {auditStoredSupplierQuote} from './supplier-evidence.ts';
import {auditStoredSourceFactsMvp163} from './source-facts.ts';
import {guardScheduledRecovery} from './scheduled-auth.ts';
import {dispatchPendingPilotSupplierPdfs,dispatchPendingVerifiedV2SupplierTexts} from './whapi-dispatch.ts';
import {sendAutomaticBuyerLinkD016} from './buyer-auto-link-d016.ts';
import {runPrivatePreanalysisVaultD016} from './internal-preanalysis-v2-d016.ts';
import {invokeAutoRecoveryMvp293} from './auto-recovery-tick-mvp293.ts';
const REF='ilggkalaafhtiysyzlmg';
const root='https://'+REF+'.supabase.co';
type Secrets={roleKey:string;apiKey:string;url:string};
function secrets():Secrets|null{
 const url=Deno.env.get('SUPABASE_URL')??'';
 let roleKey=Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')??'';
 if(!roleKey){
  try{
   const keys=JSON.parse(Deno.env.get('SUPABASE_SECRET_KEYS')??'{}');
   if(typeof keys.default==='string')roleKey=keys.default;
  }catch{return null}
 }
 const apiKey=Deno.env.get('COTIRONDA_PILOT_OPENAI_API_KEY')??'';
 if(url!==root||roleKey.length<20)return null;
 return {url,roleKey,apiKey};
}
Deno.serve(async(req)=>{
 const s=secrets();
 return guardScheduledRecovery(req,{
  enabled:s!==null&&
   Deno.env.get('COTIRONDA_PILOT_DOCUMENT_AI_ENABLED')==='true',
  authorize:async(token)=>{
   if(!s)return false;
   const db=createClient(s.url,s.roleKey,{auth:{
     autoRefreshToken:false,persistSession:false
   }});
   const {data,error}=await db.rpc('cotironda_piloto_recovery_token_allowed_mvp132',{
    p_token:token
   });
   return !error&&data===true;
  },
  run:async()=>{
   if(!s)throw Error('missing_backend');
   const db=createClient(s.url,s.roleKey,{auth:{
    autoRefreshToken:false,persistSession:false
   }});
   // This request has already passed the Vault-backed recovery-token guard.
   // Pick up any eligible supplier PDF outbox with the same SQL lease/HMAC
   // checks as Whapi. No client can invoke this worker with a browser token.
   if(Deno.env.get('COTIRONDA_PILOT_WHAPI_OUTBOUND_ENABLED')==='true'){
    try{
     await dispatchPendingPilotSupplierPdfs({
      enabled:true,
      hmacHex:Deno.env.get('COTIRONDA_PILOT_ID_HMAC_HEX')??'',
      channel:Deno.env.get('COTIRONDA_PILOT_WHAPI_CHANNEL')??'',
      token:Deno.env.get('COTIRONDA_PILOT_WHAPI_TOKEN')??'',
      recipientsJson:Deno.env.get('COTIRONDA_PILOT_RECIPIENTS_JSON')??''
     },{
      rpc:async(name,params)=>{
       const {data,error}=await db.rpc(name,params??{});
       return {data,error};
      },
      post:(url,init)=>fetch(url,init)
     });
    }catch{
     return new Response(JSON.stringify({state:'supplier_dispatch_unavailable'}),{
      status:503,headers:{'content-type':'application/json','cache-control':'no-store'}
     });
    }
   }
   // Opt-in V2: reuse this SAME Vault-authenticated cron.
   // Unlike V1, the selector requires one prepared V2 round with buyer
   // auto-approval, supplier contact permission and verified product routes.
   // No original-share policy is enabled by this worker.
   if(Deno.env.get('COTIRONDA_PILOT_WHAPI_OUTBOUND_ENABLED')==='true'){
    try{
     const delivery=await dispatchPendingVerifiedV2SupplierTexts({
      enabled:Deno.env.get('COTIRONDA_PILOT_WHAPI_OUTBOUND_ENABLED')==='true',
      dynamicRecipientsEnabled:true,
      hmacHex:Deno.env.get('COTIRONDA_PILOT_ID_HMAC_HEX')??'',
      aesHex:Deno.env.get('COTIRONDA_PILOT_AES_HEX')??'',
      channel:Deno.env.get('COTIRONDA_PILOT_WHAPI_CHANNEL')??'',
      token:Deno.env.get('COTIRONDA_PILOT_WHAPI_TOKEN')??'',
      includeReference:true
     },{
      rpc:async(name,params)=>{
       const {data,error}=await db.rpc(name,params??{});
       return {data,error};
      },
      post:(url,init)=>fetch(url,init)
     });
     if(delivery.state==='reconciliation'){
      return new Response(JSON.stringify({state:'v2_dispatch_reconciliation_required'}),{
       status:503,headers:{'content-type':'application/json','cache-control':'no-store'}
      });
     }
    }catch{
     return new Response(JSON.stringify({state:'v2_dispatch_unavailable'}),{
      status:503,headers:{'content-type':'application/json','cache-control':'no-store'}
     });
    }
   }
   // Auto D016 buyer link on the SAME Vault-authenticated cron, after
   // supplier dispatch. No new buyer command/event, no second cron.
   // Disabled unless the existing D016 + Whapi outbound flags are ON.
   if(Deno.env.get('COTIRONDA_PILOT_WHAPI_OUTBOUND_ENABLED')==='true'){
    try{
     const link=await sendAutomaticBuyerLinkD016({
      enabled:true,
      channel:Deno.env.get('COTIRONDA_PILOT_WHAPI_CHANNEL')??'',
      identityHmacHex:Deno.env.get('COTIRONDA_PILOT_ID_HMAC_HEX')??'',
      aesHex:Deno.env.get('COTIRONDA_PILOT_AES_HEX')??'',
      linkHmacHex:Deno.env.get('COTIRONDA_PILOT_D016_HMAC_KEY_HEX')??'',
      // Pinned PUBLIC pilot deployment metadata verified against Vercel READY.
      // No credentials, service keys, buyer numbers or tokens in source.
      portalOrigin:'https://app.cotironda.com',
      portalSha:'18751c1ddc8c3431d464b98ea4459795d2fdeee3',
      approvedSha:'18751c1ddc8c3431d464b98ea4459795d2fdeee3',

      whapiToken:Deno.env.get('COTIRONDA_PILOT_WHAPI_TOKEN')??''
     },{
      rpc:async(name,args)=>{
       const {data,error}=await db.rpc(name,args??{});
       return {data,error};
      },
      post:(url,init)=>fetch(url,init)
     });
     if(link.state==='reconciliation'||link.state==='uncertain'){
      return new Response(JSON.stringify({
       state:'buyer_d016_auto_link_reconciliation_required'
      }),{status:503,headers:{
       'content-type':'application/json','cache-control':'no-store'
      }});
     }
    }catch(err){
     // Report only a fixed error CATEGORY. Never expose secrets or recipient.
     let state='buyer_d016_auto_link_unavailable';
     if(err instanceof Error&&err.message==='d016_auto_link_secure_configuration_unavailable'){
      const hash=Deno.env.get('COTIRONDA_PILOT_D016_HMAC_KEY_HEX')??'';
      const origin=Deno.env.get('COTIRONDA_PILOT_D016_PORTAL_ORIGIN')??'';
      const release=Deno.env.get('COTIRONDA_PILOT_D016_PORTAL_RELEASE_SHA')??'';
      const approved=Deno.env.get('COTIRONDA_PILOT_D016_APPROVED_RELEASE_SHA')??'';
      state=!/^[a-f0-9]{64}$/u.test(hash)?'buyer_d016_hmac_not_configured':
       !/^https:\/\/cotironda-portal-[a-z0-9-]+-protector-rudo-s-projects\.vercel\.app$/u.test(origin)?
        'buyer_d016_origin_not_configured':
       !/^[a-f0-9]{40}$/u.test(release)?'buyer_d016_release_sha_not_configured':
       release!==approved?'buyer_d016_approved_release_mismatch':
        'buyer_d016_other_secure_configuration';
     }
     return new Response(JSON.stringify({state}),{
      status:503,headers:{'content-type':'application/json','cache-control':'no-store'
     }});
    }
   }
   const baseline=await runRecoveryService(req,{
    enabled:true,projectMatches:s.url===root,
    modelKeyAvailable:s.apiKey.length>=20
   },{
    lookup:async()=>{
     const {data,error}=await db.rpc('cotironda_piloto_system_document_trigger_mvp131');
     return {data,error};
    },
    reclassify:async()=>correctArchivedSupplierRole({
     lookup:async()=>{
      const {data,error}=await db.rpc('cotironda_piloto_next_supplier_role_mvp136');
      return {data,error};
     },
     download:async(path)=>{
      const {data,error}=await db.storage.from('cotironda-piloto-originals')
       .download(path);
      return {data,error};
     },
     correct:async(params)=>{
      const {data,error}=await db.rpc('cotironda_piloto_correct_supplier_role_mvp136',params);
      return {data,error};
     }
    }),
    audit:async()=>auditStoredSupplierQuote({
      lookup:async()=>{
       const {data,error}=await db.rpc('cotironda_piloto_next_supplier_evidence_mvp138');
       return {data,error};
      },
      download:async(path)=>{
       const {data,error}=await db.storage.from('cotironda-piloto-originals')
        .download(path);
       return {data,error};
      },
      record:async(params)=>{
       const {data,error}=await db.rpc('cotironda_piloto_record_supplier_evidence_mvp138',params);
       return {data,error};
      }
    }),
    sourceFacts:async()=>auditStoredSourceFactsMvp163({
      lookup:async()=>{
       const {data,error}=await db.rpc('cotironda_piloto_next_source_facts_mvp163');
       return {data,error};
      },
      download:async(path)=>{
       const {data,error}=await db.storage.from('cotironda-piloto-originals')
        .download(path);
       return {data,error};
      },
      record:async(params)=>{
       const {data,error}=await db.rpc('cotironda_piloto_record_source_facts_mvp163',params);
       return {data,error};
      }
    }),
    review:async()=>diagnoseOneStoredQuote({
     lookup:async()=>{
      const {data,error}=await db.rpc('cotironda_piloto_next_reconciliation_mvp134');
      return {data,error};
     },
     download:async(path)=>{
      const {data,error}=await db.storage.from('cotironda-piloto-originals')
       .download(path);
      return {data,error};
     },
     record:async(params)=>{
      const {data,error}=await db.rpc('cotironda_piloto_record_reconciliation_mvp134',
       params);
      return {data,error};
     }
    }),
    recover:async(triggerChatHmac)=>recoverOneStoredDocument({
     triggerChatHmac,apiKey:s.apiKey,enabled:true,io:{
      rpc:async(name,params)=>{
       const {data,error}=await db.rpc(name,params);
       return {data,error};
      },
      download:async(path)=>{
       const {data,error}=await db.storage
        .from('cotironda-piloto-originals').download(path);
       return {data,error};
      }
     }
    })
   });
   // V2: analyze stored original privately after this SAME Vault cron guard.
   // No disclosure of original bytes to buyer; no other cron or confirmation.
   try{
    const state=await runPrivatePreanalysisVaultD016({
     url:s.url,apiKey:s.apiKey,
     aesHex:Deno.env.get('COTIRONDA_PILOT_AES_HEX')??'',
     pdfEnabled:Deno.env.get('COTIRONDA_PILOT_V2_PDF_ENABLED')??'false',
     pdfSecret:Deno.env.get('COTIRONDA_PILOT_V2_PDF_SHARED_SECRET')??'',
     rpc:async(name,params)=>{
      const {data,error}=await db.rpc(name,params);
      if(error)throw Error('v2_private_analysis_database_unavailable');
      return data;
     },
     readPrivate:async(path)=>{
      const {data,error}=await db.storage.from('cotironda-piloto-originals')
       .download(path);
      if(error||!data||data.size<1||data.size>8388608)return null;
      return new Uint8Array(await data.arrayBuffer());
     }
    });
    if(state!=='idle'&&state!=='off')console.info('cotironda_v2_preanalysis',state);
   }catch{console.info('cotironda_v2_preanalysis','unavailable')}
   // Source: MVP293, from verified existing Vault-authenticated cron only.
   // A private worker failure must NEVER affect earlier recovery behavior.
   const tick=await invokeAutoRecoveryMvp293({
    enabled:Deno.env.get('COTIRONDA_PILOT_AUTO_CORRELATION_MVP291_ENABLED')==='true'&&
      Deno.env.get('COTIRONDA_PILOT_AUTO_RECOVERY_MVP292_ENABLED')==='true',
    pilotUrl:s.url,
    serviceRoleJwt:s.roleKey,
    recoverySecret:Deno.env.get('COTIRONDA_PILOT_AUTO_RECOVERY_SECRET')??'',
    post:fetch
   });
   if(tick!=='off')console.info('cotironda_mvp293_internal_tick',tick);
   return baseline;
  }
 });
});

/** D016 — automatic buyer access AFTER supplier dispatch, no buyer keyword.
 * Reuses the already installed D016 ticket issuer + one-time browser session.
 * A private SQL selector proves original buyer WhatsApp event + 2 accepted
 * supplier dispatches and returns only an AES-GCM envelope (never a number).
 * No retries of uncertain Whapi sends; no original documents are opened.
 */
import {notificarAccesoWhatsappD016} from
 '../cotironda-piloto-whapi/buyer-whatsapp-entry-d016.ts';

type Rpc=(name:string,args?:Record<string,unknown>)=>Promise<{
 data:unknown;error:unknown
}>;
type IO=Readonly<{
 rpc:Rpc;
 post:(url:string,init:RequestInit)=>Promise<Response>;
}>;
export type AutoBuyerAccessState='off'|'empty'|'api_accepted'|
 'uncertain'|'denied'|'reconciliation';
export type AutoBuyerAccessResult=Readonly<{state:AutoBuyerAccessState;attempts:0|1}>;
export type AutoBuyerConfig=Readonly<{
 enabled:boolean;
 channel:string;
 identityHmacHex:string;
 aesHex:string;
 linkHmacHex:string;
 portalOrigin:string;
 portalSha:string;
 approvedSha:string;
 whapiToken:string;
}>;
const HASH=/^[a-f0-9]{64}$/u;
const UUID=/^[a-f0-9]{8}-[a-f0-9]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[a-f0-9]{12}$/iu;
const WHAPI_CHANNEL=/^[A-Za-z0-9_-]{4,64}$/u;
const SHA=/^[a-f0-9]{40}$/u;
const CHAT=/^[1-9][0-9]{7,14}@s\.whatsapp\.net$/u;
const obj=(x:unknown):x is Record<string,unknown>=>
 x!==null&&typeof x==='object'&&!Array.isArray(x);
function freshBytes(hex:string):ArrayBuffer{
 const input=new Uint8Array(32);
 for(let i=0;i<32;i++)input[i]=parseInt(hex.slice(i*2,i*2+2),16);
 return input.buffer;
}
function toHex(data:ArrayBuffer):string{
 return [...new Uint8Array(data)].map(x=>x.toString(16).padStart(2,'0')).join('');
}
function equalHex(a:string,b:string):boolean{
 if(!HASH.test(a)||!HASH.test(b))return false;
 let d=0;
 for(let i=0;i<64;i++)d|=a.charCodeAt(i)^b.charCodeAt(i);
 return d===0;
}
function readB64(data:string):Uint8Array{
 return Uint8Array.from(atob(data),x=>x.charCodeAt(0));
}
async function decryptBuyerPacket(
 packet:Record<string,unknown>,config:AutoBuyerConfig
):Promise<string>{
 if(Object.keys(packet).length!==8||
   packet.state!=='ready'||packet.source!=='authenticated_whapi'||
   typeof packet.request_id!=='string'||!UUID.test(packet.request_id)||
   typeof packet.event_hmac!=='string'||!HASH.test(packet.event_hmac)||
   typeof packet.chat_hmac!=='string'||!HASH.test(packet.chat_hmac)||
   typeof packet.contact_sha256!=='string'||!HASH.test(packet.contact_sha256)||
   typeof packet.nonce_b64!=='string'||!/^([A-Za-z0-9+/]{16})$/u.test(packet.nonce_b64)||
   typeof packet.ciphertext_b64!=='string'||
   !/^[A-Za-z0-9+/]{20,255}={0,2}$/u.test(packet.ciphertext_b64))
  throw Error('d016_auto_buyer_contact_envelope_invalid');
 const nonce=new Uint8Array(12);
 const ciphertext=readB64(packet.ciphertext_b64);
 nonce.set(readB64(packet.nonce_b64));
 if(ciphertext.length<24||ciphertext.length>225)
  throw Error('d016_auto_buyer_ciphertext_invalid');
 const raw=new Uint8Array(ciphertext.length);
 raw.set(ciphertext);
 const key=await crypto.subtle.importKey('raw',freshBytes(config.aesHex),
  'AES-GCM',false,['decrypt']);
 const plaintext=await crypto.subtle.decrypt({
  name:'AES-GCM',iv:nonce,tagLength:128,
  additionalData:new TextEncoder().encode(packet.chat_hmac+'|cotironda-contact-v1')
 },key,raw);
 const contact=new TextDecoder('utf-8',{fatal:true}).decode(plaintext);
 if(!CHAT.test(contact))throw Error('d016_auto_buyer_recipient_not_whapi');
 const hmacKey=await crypto.subtle.importKey('raw',freshBytes(config.identityHmacHex),
  {name:'HMAC',hash:'SHA-256'},false,['sign']);
 const signed=toHex(await crypto.subtle.sign('HMAC',hmacKey,
  new TextEncoder().encode('cotironda|pilot|chat|'+config.channel+'|'+contact)));
 const sha=toHex(await crypto.subtle.digest('SHA-256',
  new TextEncoder().encode(contact)));
 if(!equalHex(signed,String(packet.chat_hmac))||
    !equalHex(sha,String(packet.contact_sha256)))
  throw Error('d016_auto_buyer_contact_integrity_failed');
 return contact;
}

/** Invoke only from the existing Vault-authenticated scheduled worker.
 * The SQL selector is the sole source of buyer identity/request/Whapi event.
 * Notifier itself rechecks ticket issuance, one-time/idempotency/quotas.
 */
export async function sendAutomaticBuyerLinkD016(
 config:AutoBuyerConfig,io:IO
):Promise<AutoBuyerAccessResult>{
 const result=(state:AutoBuyerAccessState,attempts:0|1=0)=>
  ({state,attempts} as const);
 if(!config.enabled)return result('off');
 if(!HASH.test(config.identityHmacHex)||!HASH.test(config.aesHex)||
    !HASH.test(config.linkHmacHex)||
    config.identityHmacHex===config.aesHex||
    !WHAPI_CHANNEL.test(config.channel)||
    !SHA.test(config.portalSha)||config.portalSha!==config.approvedSha||
    config.portalOrigin!=='https://app.cotironda.com'||
    typeof config.whapiToken!=='string'||config.whapiToken.length<16||
    config.whapiToken.length>300)
  throw Error('d016_auto_link_secure_configuration_unavailable');
 const selected=await io.rpc('cotironda_piloto_v2_d016_auto_buyer_packet_private');
 if(selected.error!=null||!obj(selected.data))
  throw Error('d016_auto_link_selector_unavailable');
 const packet=selected.data;
 if(packet.state==='empty')return result('empty');
 const recipient=await decryptBuyerPacket(packet,config);
 const row=await notificarAccesoWhatsappD016({
   enabled:true,webhookAutenticado:true,compradorVerificado:true,
   mode:'auto',requestId:String(packet.request_id),
   chatHmac:String(packet.chat_hmac),
   eventHmac:String(packet.event_hmac),
   recipient,portalOrigin:config.portalOrigin,
   portalSha:config.portalSha,approvedSha:config.approvedSha,
   hmacKeyHex:config.linkHmacHex,
   rpc:async(name,args)=>io.rpc(name,args),
   authorizeChat:async(value,hash)=>value===recipient&&
    equalHex(hash,String(packet.chat_hmac)),
   send:async(value,body)=>{
    if(value!==recipient)throw Error('d016_auto_buyer_receiver_changed');
    const http=await io.post('https://gate.whapi.cloud/messages/text',{
     method:'POST',headers:{
      Authorization:'Bearer '+config.whapiToken,
      'Content-Type':'application/json'
     },
     body:JSON.stringify({to:value,body}),
     signal:AbortSignal.timeout(12000)
    });
    const parsed=http.ok?await http.json().catch(()=>null):null;
    if(!obj(parsed))return {accepted:false,messageId:null};
    const nested=obj(parsed.message)?parsed.message:null;
    const id=parsed.message_id??nested?.id??parsed.id;
    return {accepted:http.ok&&parsed.sent===true,
      messageId:typeof id==='string'?id:null};
   }
 });
 const state:AutoBuyerAccessState=row.estado==='api_aceptada'?'api_accepted':
  row.estado==='entrega_incierta'?'uncertain':
  row.estado==='no_elegible'?'denied':
  row.estado==='conciliacion_requerida'?'reconciliation':
  'denied';
 return result(state,row.intentos);
}

/** D016 — puente de notificación WhatsApp al portal SIN SMS.
 * Se ejecuta SOLO después de webhook autenticado y persistencia del evento.
 * Una reserva SQL por evento = máximo un POST Whapi. Nunca reintentar
 * automáticamente ante entrega incierta; el comprador pide un enlace nuevo.
 * No crea sesión ni toca originales: el navegador abre una sesión privada renovable de 14 días.
 */
type Rpc=(name:string,args:Record<string,unknown>)=>Promise<{data:unknown;error:unknown}>;
type Send=(recipient:string,body:string)=>Promise<{accepted:boolean;messageId:string|null}>;
type Result='apagado'|'no_autorizado'|'no_elegible'|'api_aceptada'|
 'entrega_incierta'|'conciliacion_requerida';
export type ResultadoAccesoD016=Readonly<{estado:Result;intentos:0|1}>;
const result=(estado:Result,intentos:0|1=0):ResultadoAccesoD016=>
 Object.freeze({estado,intentos});
const HASH=/^[a-f0-9]{64}$/u;
const UUID=/^[a-f0-9]{8}-[a-f0-9]{4}-[1-8][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/iu;
const W=/^[1-9][0-9]{7,16}@s\.whatsapp\.net$/u;
const ID=/^[A-Za-z0-9._:-]{8,160}$/u;
const SHA=/^[a-f0-9]{40}$/u;
const enc=new TextEncoder();

/** MVP289 utilizaba DOS políticas diferentes para el mismo flag:
 * envio normal: solo "false" lo apaga;
 * recuperacion SEGUIMIENTO COTI: solo undefined o "true" lo autorizan.
 * D016 tiene su propio gate y jamás se salta el OFF general de outbound.
 */
export function permitirAvisoD016(
 outbound:boolean,d016Enabled:boolean,legacyTrackingValue:string|undefined
):boolean{
 return outbound===true&&(d016Enabled===true||legacyTrackingValue!=='false');
}
export function permitirRecuperacionD016(
 outbound:boolean,d016Enabled:boolean,legacyTrackingValue:string|undefined
):boolean{
 return outbound===true&&(d016Enabled===true||
  legacyTrackingValue===undefined||legacyTrackingValue==='true');
}


function origenD016(s:string):boolean{
 try{
  const u=new URL(s);
  return u.protocol==='https:'&&u.origin===s&&u.username===''&&
   u.password===''&&u.port===''&&u.pathname==='/'&&
   u.search===''&&u.hash===''&&
   u.hostname==='app.cotironda.com';
 }catch{return false}
}
/** D013 nunca debe publicar una ronda que el comprador no pueda abrir.
 * Es una barrera ANTES del SQL de publicación, no solo antes del WhatsApp.
 * D016 debe estar habilitado con el origen Preview y HMAC del mismo release.
 * Rechaza configuraciones incompletas o inválidas; no hace operaciones de red.
 */
export function habilitarPublicacionD013ConAccesoD016(args:{
 outbound:boolean;matchingEnabled:boolean;linkSendEnabled:boolean;
 portalOrigin:string;portalSha:string;approvedSha:string;hmacKeyHex:string;
